            load[from_r] -= demands[node]
            routes[to_r].insert(to_pos, node)
            load[to_r] += demands[node]
            moved = True
            if not routes[from_r]:
                routes.pop(from_r)
                load.pop(from_r)
            continue

        # Intra-route 2-opt (deterministic first-improvement)
        for r, rt in enumerate(routes):
            L = len(rt)
            if L < 4:
                continue
            for i in range(L - 3):
                a = rt[i]
                b = rt[i + 1]
                for k in range(i + 2, L - 1):
                    c = rt[k]
                    d = rt[k + 1]
                    delta = (matrix[a][c] + matrix[b][d]) - (matrix[a][b] + matrix[c][d])
                    if delta < 0:
                        routes[r] = rt[:i + 1] + rt[i + 1:k + 1][::-1] + rt[k + 1:]
                        load[r] = route_load(routes[r])
                        moved = True
                        break
                if moved:
                    break
            if moved:
                break

    routes = [rt for rt in routes if rt]
    return routes
